// «Docker турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

window.RUN_OK = null;
window.RUN_ERROR = null;

try {
  window.RUN_OK = runContainer("shop:1.0", {
    env: { PORT: "3000", DATABASE_URL: "postgres://db" },
    ports: ["8080:3000"],
    required: ["PORT", "DATABASE_URL"],
  });
  panel("ok", "ok", "Container ажиллаж эхэллээ", [JSON.stringify(window.RUN_OK, null, 2)]);
} catch (problem) {
  window.RUN_BOOT_ERROR = problem.message;
  panel("bad", "boot", "Container алдаа", [problem.message]);
}

try {
  runContainer("shop:1.0", { env: { PORT: "3000" }, ports: [], required: ["PORT", "DATABASE_URL"] });
  panel("bad", "missed", "Дутуу env илрээгүй", ["runContainer нь дутуу DATABASE_URL-ыг анзаарсангүй"]);
} catch (problem) {
  window.RUN_ERROR = problem.message;
  panel("ok", "err", "Дутуу env зөв илэрлээ", [problem.message]);
}
document.body.dataset.ready = "1";

