function runContainer(image, config) {
  const required = config.required || [];
  for (const key of required) {
    if (!(key in config.env)) {
      throw new Error("Орчны хувьсагч дутуу: " + key);
    }
  }
  return { image: image, env: config.env, ports: config.ports, status: "running" };
}
